impl crate::users::User {
    pub async fn find_unique<'e, E>(
        executor: E,
        w: &crate::users::UserWhereUniqueInput,
    ) -> sqlx::Result<Option<Self>>
    where
        E: sqlx::Executor<'e, Database = sqlx::Postgres>,
    {
        let cols = "\"id\", \"first_name\", \"last_name\", \"phone_number\", \"email\", \"unlimited_access\", \"token\", \"user_active\", \"role_id\", \"client_id\", \"created_at\", \"updated_at\", \"last_login_at\", \"stripe_customer_id\", \"page_credits\", \"is_converted\", \"onboarding_completed\", \"onboarding_completed_at\", \"mfa_enabled\", \"mfa_setup_dismissed_at\", \"cookie_policy_accepted_at\", \"cognito_sub\", \"firm_id\", \"firm_role_id\"";
        let mut qb = sqlx::QueryBuilder::new(format!(r#"SELECT {} FROM "users" WHERE "#, cols,));
        // For v1, support only the @id field. Composite uniques are out of scope.
        // The WhereUniqueInput has Option<T> per @id/@unique field; we pick the
        // first Some(). Multi-Some inputs cover composite uniques — TODO Task v2.
        if let Some(value) = &w.id {
            qb.push("\"id\" = ");
            qb.push_bind(value.clone());
        } else {
            return Ok(None);
        }
        qb.build_query_as::<Self>().fetch_optional(executor).await
    }
}

